const cmds = [
  ["brain_version", ["entire","brain","version"]],
  ["brain_caps", ["entire","brain","capabilities","--json"]],
  ["graph_version", ["entire","graph","version","--json"]],
  ["graph_caps", ["entire","graph","capabilities","--json"]]
];
const results = await Promise.all(cmds.map(async ([name, argv]) => {
  const r = await tools.exec_command({cmd: argv.map(x => JSON.stringify(x)).join(" "), workdir:"/Users/yueouli/ehl-challenge/Leonie", yield_time_ms:10000, max_output_tokens:12000});
  return {name, code:r.exit_code, output:r.output};
}));
results.forEach(x => { text(`## ${x.name} exit=${x.code}\n${x.output}`); });

