payload.input:
const jobs = [
  ["graph", "entire graph query --repo . --profile full --head --query \"Find RFQ agent entrypoint, browser lifecycle, planner action loop, and scouting configurator interaction paths\""],
  ["brain", "entire brain query --query \"prior signature TAN signing issues scouting tender portal configurator acknowledgment\" --json"],
  ["contract", "sed -n '1,320p' docs/PHASE1_CONTRACT.md"],
  ["fairplay", "sed -n '1,320p' \"/Users/yueouli/Desktop/Obsidian Vault/EHL Munich 2026/硬规则-Fair play.md\""],
  ["eligible", "sed -n '1,360p' \"/Users/yueouli/Desktop/Obsidian Vault/EHL Munich 2026/第一阶段-Get eligible first.md\""]
];
const out = await Promise.all(jobs.map(async ([name, cmd]) => {
  const r = await tools.exec_command({cmd, workdir:"/Users/yueouli/ehl-challenge/Leonie", yield_time_ms:30000, max_output_tokens:30000});
  return {name, code:r.exit_code, output:r.output};
}));
out.forEach(x => text(`## ${x.name} exit=${x.code}\n${x.output}`));

